import{_ as e,o as n,c as h,a2 as i}from"./chunks/framework.62rcL0wY.js";const u=JSON.parse('{"title":"Lịch sử phát triển phiên bản","description":"","frontmatter":{},"headers":[],"relativePath":"phu-luc/lich-su.md","filePath":"phu-luc/lich-su.md"}'),o={name:"phu-luc/lich-su.md"};function l(d,c,t,a,r,m){return n(),h("div",null,[...c[0]||(c[0]=[i('<h1 id="lich-su-phat-trien-phien-ban" tabindex="-1">Lịch sử phát triển phiên bản <a class="header-anchor" href="#lich-su-phat-trien-phien-ban" aria-label="Permalink to &quot;Lịch sử phát triển phiên bản&quot;">​</a></h1><p>Trang này dịch các ý chính trong lịch sử các phiên bản của Clickermann từ bản v1.0 đến v4.13.014 theo phần Lịch sử phiên bản trong help chính thức, giúp tra cứu xem lệnh hoặc tính năng nào xuất hiện hay bị loại bỏ từ phiên bản nào.</p><h2 id="phien-ban-v4-13-014-16-05-2018" tabindex="-1">Phiên bản v4.13.014 (16.05.2018) <a class="header-anchor" href="#phien-ban-v4-13-014-16-05-2018" aria-label="Permalink to &quot;Phiên bản v4.13.014 (16.05.2018)&quot;">​</a></h2><ul><li><strong>Nhân chương trình (Core):</strong><ul><li>Chuyển sang bảng mã Unicode, các tệp văn bản nay sử dụng mã hóa UTF-8.</li><li>Tạo thêm phiên bản 64-bit của chương trình.</li><li>Cải thiện hỗ trợ màn hình mở rộng (nhiều màn hình).</li><li>Sửa lỗi treo/sập khi hệ điều hành chạy liên tục quá 49 ngày không khởi động lại.</li></ul></li><li><strong>Trình soạn thảo:</strong><ul><li>Khóa chỉnh sửa mã nguồn trong lúc script đang chạy.</li><li>Tăng tốc độ hoạt động của kính lúp.</li><li>Sửa lỗi các menu thả xuống, lỗi tính năng tự động chú thích dòng (auto-commenting) và lỗi thu nhỏ/phóng to cửa sổ.</li><li>Sửa lỗi sập chương trình khi phần tử đang khóa bị đóng.</li><li>Cửa sổ trình soạn thảo nay ghi nhớ vị trí khi chuyển qua lại với cửa sổ chính.</li><li>Thêm phím tắt <code>Ctrl + S</code> để lưu nhanh; thêm <code>Tab</code> và <code>Shift + Tab</code> để thụt lề theo khối.</li><li>Cho phép đặt mẫu script mặc định qua tệp <code>\\data\\default.txt</code>.</li><li>Thêm tính năng chụp nhanh ảnh <code>100×100</code> quanh vị trí con trỏ (ảnh chụp kính lúp) cùng phím tắt toàn cục <code>Alt + G</code> (có thể đổi được).</li></ul></li><li><strong>Trình thông dịch:</strong><ul><li>Thêm bước kiểm tra cú pháp cơ bản.</li><li>Thêm các lệnh mới: <a href="/clickermann-guide-vi/lenh/winapi.html#hgetpid"><code>HGETPID</code></a>, <a href="/clickermann-guide-vi/lenh/so.html#arrsort"><code>ARRSORT</code></a>, <a href="/clickermann-guide-vi/lenh/winapi.html#getmessage"><code>GETMESSAGE</code></a>, <a href="/clickermann-guide-vi/lenh/chuoi-file.html#char"><code>CHAR</code></a>.</li><li>Thêm các biến hệ thống: <code>$_pdir</code>, <code>$_hwnd</code>, <code>$_hwnd_self</code>, <code>$_time_str</code>, <code>$_date_str</code>, <code>$_ver_self</code>, <code>$_ver_sys</code>, <code>$_arch_sys</code>, <code>$_param_str</code>.</li><li>Các sửa đổi và nâng cấp: <ul><li>Cải tiến toàn bộ phần toán học, bổ sung các phép toán mới.</li><li>Nâng cấp các hàm tìm kiếm đồ họa, tăng nhẹ tốc độ tìm kiếm.</li><li>Thay đổi tham số của <a href="/clickermann-guide-vi/lenh/kich-ban.html#writemem"><code>WRITEMEM</code></a> và <a href="/clickermann-guide-vi/lenh/kich-ban.html#readmem"><code>READMEM</code></a>; nâng cấp <code>READMEM()</code> thành hàm trả về giá trị.</li><li>Nâng cấp <a href="/clickermann-guide-vi/lenh/chuoi-file.html#strpos"><code>STRPOS</code></a>, thêm tham số độ lệch bắt đầu tìm (<code>offset</code>).</li><li>Nâng cấp <a href="/clickermann-guide-vi/lenh/so.html#dist"><code>DIST</code></a>, hỗ trợ tham số số thập phân có dấu chấm.</li><li>Nâng cấp <a href="/clickermann-guide-vi/lenh/ban-phim.html#keystring"><code>KEYSTRING</code></a>, nay tự động nhấn giữ phím <code>Shift</code> khi cần.</li><li>Sửa lỗi <a href="/clickermann-guide-vi/lenh/kich-ban.html#getfilelist"><code>GETFILELIST</code></a> và <a href="/clickermann-guide-vi/lenh/kich-ban.html#getdirlist"><code>GETDIRLIST</code></a>.</li><li>Sửa một số lỗi liên quan tới dấu ngoặc kép trong chuỗi trả về.</li><li>Ở chế độ khóa cửa sổ, hình ảnh không còn bị trượt lệch.</li><li><a href="/clickermann-guide-vi/lenh/man-hinh.html#screenshotfix"><code>SCREENSHOTFIX</code></a> không còn tự tạo thư mục rỗng.</li><li>Sửa một số lỗi của luồng (<code>THREAD</code>).</li><li>Cảnh báo khi tệp nêu trong <code>#include</code> không tồn tại.</li><li>Nâng cấp <code>#logfile</code>, cho phép đặt tên tệp nhật ký tùy ý.</li><li>Các thủ tục điều khiển con trỏ chuột không còn bấm tại vị trí hiện tại nếu cả hai tọa độ đều mang số âm.</li></ul></li></ul></li><li><strong>Khác:</strong><ul><li>Loại bỏ sự phụ thuộc vào thư viện <code>httpwork.dll</code>.</li><li>Cập nhật lại tài liệu hướng dẫn (<code>help.chm</code>) và tối ưu hóa chung.</li></ul></li></ul><h2 id="phien-ban-v4-12-001-25-03-2016" tabindex="-1">Phiên bản v4.12.001 (25.03.2016) <a class="header-anchor" href="#phien-ban-v4-12-001-25-03-2016" aria-label="Permalink to &quot;Phiên bản v4.12.001 (25.03.2016)&quot;">​</a></h2><ul><li><strong>Trình thông dịch:</strong><ul><li>Thêm các lệnh: <a href="/clickermann-guide-vi/lenh/kich-ban.html#radiobox"><code>RADIOBOX</code></a>, <a href="/clickermann-guide-vi/lenh/ban-phim.html#getkeysdown"><code>GETKEYSDOWN</code></a>, <a href="/clickermann-guide-vi/lenh/kich-ban.html#getdirlist"><code>GETDIRLIST</code></a>, <a href="/clickermann-guide-vi/lenh/kich-ban.html#getfilelist"><code>GETFILELIST</code></a>, <a href="/clickermann-guide-vi/lenh/so.html#setvar"><code>SETVAR</code></a>, <a href="/clickermann-guide-vi/lenh/so.html#getvar"><code>GETVAR</code></a>, <a href="/clickermann-guide-vi/lenh/man-hinh.html#screenshotfix"><code>SCREENSHOTFIX</code></a>, <a href="/clickermann-guide-vi/lenh/man-hinh.html#pxlreplace"><code>PXLREPLACE</code></a>.</li><li>Loại bỏ lệnh: <code>LOAD</code>.</li><li>Thay đổi lệnh: <a href="/clickermann-guide-vi/lenh/cau-truc.html#setthread"><code>SETTHREAD</code></a>.</li></ul></li><li><strong>Khác:</strong><ul><li>Sửa lỗi với các chuỗi có chứa ký tự <code>$</code>.</li><li>Sửa lỗi rò rỉ bộ nhớ (memory leak) khi bật chế độ khóa cửa sổ.</li><li>Sửa lỗi treo chương trình trong một số trường hợp khi đọc chuỗi.</li><li>Sửa lỗi lệnh <a href="/clickermann-guide-vi/lenh/so.html#inc"><code>INC</code></a>.</li><li>Khi bỏ tạm dừng (Resume) chương trình, các luồng đã bị dừng bởi script trước đó sẽ không tự động chạy lại.</li><li>Hiệu chỉnh lại tính năng ghi thao tác (Record) và tối ưu hóa.</li></ul></li></ul><h2 id="phien-ban-v4-11-000-15-10-2014" tabindex="-1">Phiên bản v4.11.000 (15.10.2014) <a class="header-anchor" href="#phien-ban-v4-11-000-15-10-2014" aria-label="Permalink to &quot;Phiên bản v4.11.000 (15.10.2014)&quot;">​</a></h2><ul><li><strong>Nhân chương trình:</strong> Thêm hỗ trợ đa luồng (multithreading).</li><li><strong>Giao diện:</strong><ul><li>Giao diện cài đặt phím tắt mới (không tương thích với tệp <code>config.ini</code> cũ).</li><li>Thêm nút &quot;Luôn nổi trên cùng&quot; (Always on top) trên cửa sổ chính.</li><li>Thanh trạng thái ở cửa sổ chính hiển thị dòng nhật ký mới nhất.</li><li>Trong cài đặt có thêm nút đăng ký và gỡ liên kết định dạng tệp <code>.cms</code> (trước đây tự ghi vào Registry mỗi khi khởi động).</li></ul></li><li><strong>Trình thông dịch:</strong><ul><li>Thêm các lệnh: <a href="/clickermann-guide-vi/lenh/chuoi-file.html#tfreadarr"><code>TFREADARR</code></a>, <a href="/clickermann-guide-vi/lenh/chuoi-file.html#tfwritearr"><code>TFWRITEARR</code></a>, <a href="/clickermann-guide-vi/lenh/chuoi-file.html#strseparate"><code>STRSEPARATE</code></a>, <a href="/clickermann-guide-vi/lenh/cau-truc.html#thread-end-thread"><code>THREAD ... END_THREAD</code></a>, <a href="/clickermann-guide-vi/lenh/cau-truc.html#setthread"><code>SETTHREAD</code></a>, <a href="/clickermann-guide-vi/lenh/so.html#arcsin"><code>ARCSIN</code></a>, <a href="/clickermann-guide-vi/lenh/so.html#arccos"><code>ARCCOS</code></a>, <a href="/clickermann-guide-vi/lenh/winapi.html#wndgetinfo"><code>WNDGETINFO</code></a>, <a href="/clickermann-guide-vi/lenh/winapi.html#wndsetinfo"><code>WNDSETINFO</code></a>, <a href="/clickermann-guide-vi/lenh/winapi.html#wndbump"><code>WNDBUMP</code></a>.</li><li>Thêm các tham số tọa độ vùng cho <a href="/clickermann-guide-vi/lenh/man-hinh.html#getscreen"><code>GETSCREEN</code></a>.</li><li>Thêm macro cho bộ tiền xử lý (Suy luận: <code>#define</code>).</li><li>Sửa lỗi: lồng nhiều <code>SWITCH</code> không còn làm treo chương trình; &quot;Thay thế tất cả&quot; trong trình soạn thảo không làm treo chương trình; vòng lặp <code>FOR</code> không tự đưa biến đếm về <code>0</code> nếu biến đó đã được khởi tạo từ trước.</li></ul></li><li><strong>Khác:</strong> Gộp hai tệp hướng dẫn thành một tệp <code>help.chm</code> duy nhất.</li></ul><h2 id="phien-ban-v4-10-000-03-04-2014" tabindex="-1">Phiên bản v4.10.000 (03.04.2014) <a class="header-anchor" href="#phien-ban-v4-10-000-03-04-2014" aria-label="Permalink to &quot;Phiên bản v4.10.000 (03.04.2014)&quot;">​</a></h2><ul><li><strong>Nhân chương trình:</strong><ul><li>Độ dài dữ liệu lưu trong biến không còn bị giới hạn ở 255 ký tự.</li><li>Viết lại hoàn toàn cơ chế ghi thao tác (Record) chính xác hơn.</li><li>Hỗ trợ đầy đủ màn hình mở rộng (Extended Desktop).</li></ul></li><li><strong>Trình thông dịch:</strong><ul><li>Viết lại phần xử lý logic: thêm phép toán bit và hỗ trợ ngoặc tròn ưu tiên <code>( )</code>.</li><li>Thêm mức lọc thứ 8 cho <a href="/clickermann-guide-vi/lenh/man-hinh.html#colormode"><code>COLORMODE</code></a>.</li><li>Vòng lặp <a href="/clickermann-guide-vi/lenh/cau-truc.html#for-end-cyc"><code>FOR</code></a> cho phép gán giá trị khởi tạo ban đầu ngay ở tham số đầu tiên.</li></ul></li></ul><h2 id="phien-ban-v4-9-31-12-2013" tabindex="-1">Phiên bản v4.9 (31.12.2013) <a class="header-anchor" href="#phien-ban-v4-9-31-12-2013" aria-label="Permalink to &quot;Phiên bản v4.9 (31.12.2013)&quot;">​</a></h2><ul><li><strong>Trình thông dịch:</strong><ul><li>Thêm cấu trúc <a href="/clickermann-guide-vi/lenh/cau-truc.html#switch-end-switch"><code>SWITCH</code></a>.</li><li>Thay đổi cách khai báo và gọi chương trình con <a href="/clickermann-guide-vi/lenh/cau-truc.html#sub-end-sub"><code>SUB</code></a>, nay hỗ trợ truyền tham số (không còn dùng <code>callsub</code>).</li><li>Thay đổi vòng lặp <code>FOR</code>: lượt lặp đầu tiên bắt đầu từ <code>0</code>.</li><li>Hàm <a href="/clickermann-guide-vi/lenh/so.html#dist"><code>DIST</code></a> trả về số thực dấu chấm động.</li><li>Viết lại <a href="/clickermann-guide-vi/lenh/kich-ban.html#dialogbox"><code>DIALOGBOX</code></a> và <a href="/clickermann-guide-vi/lenh/kich-ban.html#inputbox"><code>INPUTBOX</code></a> (hỗ trợ phím <code>Enter</code> và <code>Esc</code>).</li><li>Nâng cấp <a href="/clickermann-guide-vi/lenh/kich-ban.html#halt"><code>HALT</code></a>, cho phép đóng hoàn toàn chương trình Clickermann.</li><li>Sửa lỗi dòng trống, lỗi 6 tham số, lỗi hàm <code>SIN</code> và <code>COS</code>, lỗi tính toán số có nhiều chữ số thập phân; mảng nay chứa được cả phần tử chuỗi lẫn số.</li></ul></li></ul><h2 id="phien-ban-v4-8-000-01-10-2013" tabindex="-1">Phiên bản v4.8.000 (01.10.2013) <a class="header-anchor" href="#phien-ban-v4-8-000-01-10-2013" aria-label="Permalink to &quot;Phiên bản v4.8.000 (01.10.2013)&quot;">​</a></h2><ul><li><strong>Nhân chương trình:</strong> Thêm chế độ PS/2.</li><li><strong>Trình thông dịch:</strong><ul><li>Thêm các chỉ thị: <code>#logfile</code>, <code>#autorun</code>, <code>#ps2_mouse</code>, <code>#ps2_keyboard</code>.</li><li>Thêm hỗ trợ mảng và các lệnh: <a href="/clickermann-guide-vi/lenh/so.html#arrpush"><code>ARRPUSH</code></a>, <a href="/clickermann-guide-vi/lenh/so.html#arrpop"><code>ARRPOP</code></a>, <a href="/clickermann-guide-vi/lenh/so.html#arrsize"><code>ARRSIZE</code></a>, <a href="/clickermann-guide-vi/lenh/man-hinh.html#scanpxl"><code>SCANPXL</code></a>, <a href="/clickermann-guide-vi/lenh/man-hinh.html#scanpicture"><code>SCANPICTURE</code></a>, <a href="/clickermann-guide-vi/lenh/kich-ban.html#dialogbox"><code>DIALOGBOX</code></a>.</li><li><a href="/clickermann-guide-vi/lenh/kich-ban.html#wait"><code>WAIT</code></a> nhận được số thập phân (ví dụ <code>wait(1.5)</code> tương đương <code>waitms(1500)</code>).</li></ul></li><li><strong>Giao diện:</strong> Thêm lịch sử các tệp đã mở.</li></ul><h2 id="phien-ban-v4-7-000-se-05-12-2012" tabindex="-1">Phiên bản v4.7.000 SE (05.12.2012) <a class="header-anchor" href="#phien-ban-v4-7-000-se-05-12-2012" aria-label="Permalink to &quot;Phiên bản v4.7.000 SE (05.12.2012)&quot;">​</a></h2><ul><li><strong>Trình thông dịch:</strong><ul><li>Bộ phân tích cú pháp không còn cố tính toán bên trong chuỗi văn bản.</li><li>Sửa lỗi <code>PXLCRC</code>, <code>ROUND</code>, <code>WNDFIND</code>, lỗi cộng nhiều hàm, lỗi so sánh số thập phân trong câu điều kiện và lỗi chỉ thị có chú thích đi sau.</li><li>Thêm các lệnh: <a href="/clickermann-guide-vi/lenh/so.html#pow"><code>POW</code></a>, <a href="/clickermann-guide-vi/lenh/chuoi-file.html#tfread"><code>TFREAD</code></a>, <a href="/clickermann-guide-vi/lenh/chuoi-file.html#tfwrite"><code>TFWRITE</code></a>, <a href="/clickermann-guide-vi/lenh/chuoi-file.html#tfdelete"><code>TFDELETE</code></a>, <a href="/clickermann-guide-vi/lenh/chuoi-file.html#tfclear"><code>TFCLEAR</code></a>, <a href="/clickermann-guide-vi/lenh/chuoi-file.html#tfcount"><code>TFCOUNT</code></a>, <a href="/clickermann-guide-vi/lenh/ban-phim.html#getkblayout"><code>GETKBLAYOUT</code></a>, <a href="/clickermann-guide-vi/lenh/ban-phim.html#setkblayout"><code>SETKBLAYOUT</code></a>.</li><li>Nâng cấp <a href="/clickermann-guide-vi/lenh/man-hinh.html#if-picture-in-end-if"><code>IF_PICTURE_IN</code></a>.</li><li>Thêm biến hệ thống: <code>$_DATE_Y</code>, <code>$_DATE_M</code>, <code>$_DATE_D</code>.</li></ul></li><li><strong>Trình soạn thảo &amp; Giao diện:</strong> Thêm menu chèn nhanh lệnh, menu mẫu code thả xuống; bật kính lúp tự làm chậm tốc độ con trỏ chuột; các chế độ thực thi trở lại dưới dạng một cửa sổ riêng.</li></ul><h2 id="phien-ban-v4-7-000-12-10-2012" tabindex="-1">Phiên bản v4.7.000 (12.10.2012) <a class="header-anchor" href="#phien-ban-v4-7-000-12-10-2012" aria-label="Permalink to &quot;Phiên bản v4.7.000 (12.10.2012)&quot;">​</a></h2><ul><li><strong>Nhân chương trình:</strong><ul><li>Thêm tính năng tạm dừng (Pause) script.</li><li>Cho phép dùng đường dẫn tuyệt đối tới tệp (đường dẫn tương đối vẫn được tính từ thư mục dự án hiện tại), viết số hệ 16 (<code>0x...</code>) và số thập phân có dấu chấm.</li><li>Hợp nhất kiểu biến: biến có thể nhận số nguyên, số thực hoặc chuỗi.</li></ul></li><li><strong>Trình thông dịch:</strong><ul><li>Hỗ trợ viết <code>AND</code>, <code>OR</code>, <code>XOR</code> trong điều kiện (thay cho <code>&amp;</code>, <code>|</code>, <code>^</code>).</li><li>Thay đổi cơ chế giảm màu và thủ tục <a href="/clickermann-guide-vi/lenh/man-hinh.html#colormode"><code>COLORMODE</code></a>.</li><li>Thêm các lệnh: <a href="/clickermann-guide-vi/lenh/chuot.html#mclick-mdown-mup"><code>MCLICK</code></a>, <code>MDOWN</code>, <code>MUP</code>, <a href="/clickermann-guide-vi/lenh/chuoi-file.html#iniread"><code>INIREAD</code></a>, <a href="/clickermann-guide-vi/lenh/chuoi-file.html#iniwrite"><code>INIWRITE</code></a>, <a href="/clickermann-guide-vi/lenh/man-hinh.html#pxlcrc"><code>PXLCRC</code></a>, <a href="/clickermann-guide-vi/lenh/so.html#sin"><code>SIN</code></a>, <a href="/clickermann-guide-vi/lenh/so.html#cos"><code>COS</code></a>, <a href="/clickermann-guide-vi/lenh/so.html#sqrt"><code>SQRT</code></a>, <a href="/clickermann-guide-vi/lenh/so.html#round"><code>ROUND</code></a>, <a href="/clickermann-guide-vi/lenh/so.html#int"><code>INT</code></a>.</li><li>Thêm biến hệ thống <code>$_hwnd</code>; loại bỏ hai lệnh <code>TOINT</code>, <code>TOSTR</code>.</li></ul></li><li><strong>Trình soạn thảo &amp; Giao diện:</strong> Thêm nút chuyển chế độ chép tọa độ vào Clipboard, tìm kiếm/thay thế, tự động căn lề, đổi mức giảm màu trên kính lúp, xem/sửa giá trị biến khi đang tạm dừng; gỡ bỏ các chế độ hoạt động khỏi cửa sổ chính.</li></ul><h2 id="cac-phien-ban-tu-v1-0-den-v4-6-000-2006-2012" tabindex="-1">Các phiên bản từ v1.0 đến v4.6.000 (2006 – 2012) <a class="header-anchor" href="#cac-phien-ban-tu-v1-0-den-v4-6-000-2006-2012" aria-label="Permalink to &quot;Các phiên bản từ v1.0 đến v4.6.000 (2006 – 2012)&quot;">​</a></h2><ul><li><strong>v4.6.000 (09.03.2012):</strong> Đưa vào khái niệm &quot;thư mục dự án&quot; — nay mọi đường dẫn đều được tính tương đối theo thư mục chứa tệp script đang nạp; thêm <code>#include</code>, <code>#name</code>, <a href="/clickermann-guide-vi/lenh/nhat-ky.html#hintpopup"><code>HINTPOPUP</code></a>, <a href="/clickermann-guide-vi/lenh/chuoi-file.html#strmd5"><code>STRMD5</code></a>, <a href="/clickermann-guide-vi/lenh/chuoi-file.html#strcut2"><code>STRCUT2</code></a>; thêm mẫu code trong trình soạn thảo.</li><li><strong>v4.5.000 (16.09.2011):</strong> Hỗ trợ lưu ảnh chụp JPEG; thêm <a href="/clickermann-guide-vi/lenh/kich-ban.html#inputbox"><code>INPUTBOX</code></a>, <a href="/clickermann-guide-vi/lenh/man-hinh.html#if-picture-in-end-if"><code>IF_PICTURE_IN</code></a>, <a href="/clickermann-guide-vi/lenh/ban-phim.html#iskeydown"><code>ISKEYDOWN</code></a>, <a href="/clickermann-guide-vi/lenh/chuoi-file.html#httpget"><code>HTTPGET</code></a>; cho phép nhập tay <code>HWND</code> trong Quản lý cửa sổ.</li><li><strong>v4.4.000 (20.07.2011):</strong> Giảm mạnh sai số của <code>WAIT</code>, <code>WAITMS</code>; thêm kính lúp màn hình; <code>GOTO</code> chỉ còn dùng nhãn chữ; thêm bộ lệnh chuỗi (<code>STRFILTER</code>, <code>STRCUT</code>, <code>STRLEN</code>, <code>STRCONCAT</code>, <code>STRREPLACE</code>, <code>STRREADLN</code>, <code>STRWRITELN</code>), bộ lệnh cửa sổ (<code>WNDFIND</code>, <code>WNDSIZE</code>, <code>WNDPOS</code>, <code>WNDSTATE</code>, <code>POSTMESSAGE</code>, <code>SENDMESSAGE</code>), bộ lệnh kênh màu (<code>COLORGEN</code>, <code>COLORR</code>, <code>COLORG</code>, <code>COLORB</code>) và <code>BEEP</code>.</li><li><strong>v4.3.000 (26.11.2010):</strong> Hỗ trợ đa ngôn ngữ giao diện; thêm <code>$_time_h</code>, <code>$_time_m</code>, <code>$_time_s</code>, <code>HSET</code>, <code>HSETTEXT</code>, <code>HGET</code>, <code>HGETTEXT</code>.</li><li><strong>v4.2.000 (05.10.2010):</strong> Hỗ trợ điều kiện phức hợp cho <code>IF</code>, <code>FOR</code>, <code>WHILE</code>; tham số vòng lặp <code>FOR</code> được đưa về <code>0</code> sau khi kết thúc vòng lặp; thêm <code>COLORMODE</code>, <code>MOVER</code>, <code>$_xmax</code>, <code>$_ymax</code>, <code>$_time_t</code>.</li><li><strong>v4.1.000 (02.09.2010):</strong> Thêm giảm màu; thêm <code>DIST</code>, <code>READMEM</code>, <code>WRITEMEM</code>, <code>SUB ... END_SUB</code>, <code>GOSUB</code>; tự lưu <code>backup.cms</code> khi bấm Áp dụng.</li><li><strong>v4.0.002 (11.06.2010):</strong> Hỗ trợ plugin DLL, biến chuỗi, nhánh <code>ELSE</code>, nhãn chữ cho <code>GOTO</code>, tệp hằng <code>/data/const.txt</code>; thêm <code>PXL</code>, <code>PXLXOR</code>, <code>PXLCOUNT</code>, <code>RND</code>, <code>RNDFROM</code>, <code>FROMCLIP</code>, <code>BREAK</code>, <code>CALL</code>.</li><li><strong>v3.2 RC1 &amp; v3.2 beta (02–03.2010):</strong> Thêm <code>IF ... END_IF</code>, <code>DEFINE</code>, <code>UNDEFINE</code>, vòng lặp <code>FOR</code>, <code>WHILE</code>, phân tích màn hình ở chế độ khóa cửa sổ, biến <code>$_line</code>, <code>$_cursor</code>, lệnh <code>IF_KEYDOWN</code>, <code>TOCLIP</code>.</li><li><strong>v3.1 (12.2009 – 01.2010):</strong> Thêm chế độ khóa cửa sổ, cửa sổ nhật ký (<code>LOGSHOW</code>, <code>LOGCLEAR</code>, <code>LOGWRITE</code>), <code>GETSCREEN</code>, <code>SCREENSHOT</code>, <code>INC</code>, <code>HALT</code>, <code>$_return1</code>, <code>$_return2</code>, <code>IF_PIXEL_IN</code>, <code>SOUND</code>, <code>KEYSTRING</code>, <code>$_xmouse</code>, <code>$_ymouse</code>, <code>IF_TIME</code>.</li><li><strong>v1.0 – v3.0 (2006 – 09.2009):</strong> Các phiên bản đầu tiên: đổi tên thành Clickermann (v1.1), thêm các lệnh chuột <code>LCLICK</code>, <code>RCLICK</code>, <code>LDOWN</code>, <code>LUP</code>, chức năng ghi thao tác (v1.3), tô màu cú pháp và chú thích <code>//</code> (v2.1), hỗ trợ biến và <code>GOTO</code> (v3.0).</li></ul>',20)])])}const s=e(o,[["render",l]]);export{u as __pageData,s as default};
